// Enhanced data preparation for Agent
const item = $input.first().json;

const userQuery = item.chatInput || '';
const fileContext = item.upload_file_context || '';
const fileMetadata = item.file_metadata || {};

// Enhanced URL extraction with validation
const urlRegex = /https?:\/\/(?:[-\w.])+(?::[0-9]+)?(?:\/(?:[\w\._~!$&'()*+,;=:@]|%[0-9a-fA-F]{2})*)*(?:\?(?:[\w\._~!$&'()*+,;=:@\/?]|%[0-9a-fA-F]{2})*)?(?:#(?:[\w\._~!$&'()*+,;=:@\/?]|%[0-9a-fA-F]{2})*)?/g;
const extractedUrls = userQuery.match(urlRegex) || [];

// Clean query by removing URLs
const cleanedQuery = userQuery.replace(urlRegex, '').trim();

// Default n8n documentation sources
const defaultSources = [
  'https://docs.n8n.io/glossary/',
  'https://docs.n8n.io/workflows/',
  'https://docs.n8n.io/integrations/'
];

// Combine extracted URLs with defaults (remove duplicates)
const allSources = [...new Set([...extractedUrls, ...defaultSources])];

// Enhanced query construction
let enhancedQuery = cleanedQuery;

// Add file context if available
if (fileContext && fileContext.trim() !== '') {
  enhancedQuery += `\n\n--- UPLOADED FILE CONTEXT ---\n`;

  // Add file metadata
  if (fileMetadata.filename) {
    enhancedQuery += `File: ${fileMetadata.filename}\n`;
  }
  if (fileMetadata.type) {
    enhancedQuery += `Type: ${fileMetadata.type}\n`;
  }

  enhancedQuery += `Content:\n${fileContext}`;
}

// Add context about the request type
if (cleanedQuery.toLowerCase().includes('workflow')) {
  enhancedQuery += `\n\n--- WORKFLOW CONTEXT ---\nUser is requesting n8n workflow creation or modification.`;
}

// Validate and prepare final output
const output = {
  ...item,
  cleaned_query: cleanedQuery,
  enhanced_query: enhancedQuery,
  upload_file_context: fileContext,
  file_metadata: fileMetadata,
  sources: allSources,
  timestamp: new Date().toISOString(),
  query_length: cleanedQuery.length,
  has_file: fileContext.length > 0
};

return output;
